import{_ as t,o as a,c as o,a5 as i}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Plan — Apply Hashtag to a Post Draft","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/apply-hashtag-to-post/plan.md","filePath":"feature/content-task-workflow/apply-hashtag-to-post/plan.md"}'),s={name:"feature/content-task-workflow/apply-hashtag-to-post/plan.md"};function r(n,e,l,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="plan-—-apply-hashtag-to-a-post-draft" tabindex="-1">Plan — Apply Hashtag to a Post Draft <a class="header-anchor" href="#plan-—-apply-hashtag-to-a-post-draft" aria-label="Permalink to &quot;Plan — Apply Hashtag to a Post Draft&quot;">​</a></h1><h2 id="module-and-seam" tabindex="-1">Module and seam <a class="header-anchor" href="#module-and-seam" aria-label="Permalink to &quot;Module and seam&quot;">​</a></h2><p>Use the existing Post editor as the feature module&#39;s interface. The web picker reads and creates collection entries through the already implemented Hashtag API, then changes the editor&#39;s hashtag state. Existing Post draft create/update APIs persist the selected display strings in Mongo as Post snapshots. There is no new Business endpoint, JPA entity, Mongo field, or migration.</p><p>The collection&#39;s entry action navigates to the workspace Post editor with the selected display tag in location state. The editor&#39;s current <code>useEditorForm</code> already accepts <code>prefilledHashtags</code>, so the route can reuse this path without inventing a Post identifier or existing-draft lookup.</p><h2 id="flow" tabindex="-1">Flow <a class="header-anchor" href="#flow" aria-label="Permalink to &quot;Flow&quot;">​</a></h2><ol><li>Resolve the workspace from the editor route/current workspace and the authenticated user.</li><li>Query active workspace hashtags through <code>useHashtagCollection</code>; include workspace and user in the query key.</li><li>Search the collection from the existing hashtag input; selecting entries adds their display tag to editor state, deduplicated by normalized tag.</li><li>Keep campaign-required entries visible but disabled because <code>PostDocument</code> has no campaign ID.</li><li>For an unmatched typed tag, open <code>AddHashtagDialog</code> with the typed value. Create it with the chosen non-required purpose; after success, add its display tag to editor state. Reuse the existing create mutation and query invalidation.</li><li>On “Apply to Post” from the collection page, navigate to <code>/workspaces/{workspaceId}/editor</code> with the selected hashtag prefilled.</li><li>Let the existing Post auto-save or submit flow persist <code>hashtags</code> as immutable display text on the Post snapshot.</li></ol><h2 id="files" tabindex="-1">Files <a class="header-anchor" href="#files" aria-label="Permalink to &quot;Files&quot;">​</a></h2><ul><li>Modify <code>brandhub-web/src/pages/editor/components/HashtagInputWithSuggestions.tsx</code> to load/search/select workspace entries, open the Add dialog for unmatched tags, and report loading/empty/error/scope states.</li><li>Modify <code>brandhub-web/src/pages/editor/index.tsx</code> to provide workspace/user/role context to the picker.</li><li>Modify <code>brandhub-web/src/pages/editor/hooks/useEditorForm.ts</code> only if needed to make location-prefilled tags merge/deduplicate consistently.</li><li>Modify <code>brandhub-web/src/pages/hashtag-groups/components/HashtagCollection.tsx</code> to show a Creator-only Apply-to-Post action for ordinary entries.</li><li>Keep <code>HashtagCollection.tsx</code> as the collection orchestrator; render filters and entry cards through <code>HashtagCollectionFilters.tsx</code> and <code>HashtagEntryGrid.tsx</code> so each module stays focused and the page JSX remains below the repository guideline.</li><li>Keep the card&#39;s navigation in <code>ApplyHashtagToPostButton.tsx</code> and pagination in <code>HashtagCollectionPagination.tsx</code>, each behind a small prop interface.</li><li>Modify <code>brandhub-web/src/pages/hashtag-groups/components/AddHashtagDialog.tsx</code> to accept an optional initial tag while retaining explicit purpose selection.</li><li>Reuse <code>brandhub-web/src/pages/hashtag-groups/hooks/useHashtagCollection.ts</code>, <code>services/hashtagService.ts</code>, and the existing Add dialog; avoid duplicating collection queries or mutations.</li><li>Add editor labels in <code>src/i18n/locales/{en,vi}/editor.json</code> and collection action labels in <code>src/i18n/locales/{en,vi}/hashtagGroups.json</code>.</li><li>Add the agreed browser-flow coverage in <code>brandhub-web/tests/e2e/editor/content-creator-studio.spec.ts</code>; add a collection navigation case in <code>tests/e2e/hashtags/collection.spec.ts</code>.</li></ul><h2 id="data-and-risks" tabindex="-1">Data and risks <a class="header-anchor" href="#data-and-risks" aria-label="Permalink to &quot;Data and risks&quot;">​</a></h2><ul><li>Post snapshot is the hashtag text copied into existing <code>PostDocument.hashtags</code>; later collection edits/removal do not rewrite Posts.</li><li>Collection creation commits to PostgreSQL separately from a later Post save in Mongo. The UI reports creation and keeps the tag available if saving the draft later fails; it does not claim a distributed transaction.</li><li>Required <code>EVENT_SPECIFIC</code> tags remain unavailable until a Post-to-campaign link exists.</li><li>Existing editor save/submit error behavior and permission enforcement remain unchanged. Collection-Apply controls are Creator-only.</li><li>No new AI/provider, gateway route, publisher/mobile change, or database migration.</li></ul><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><ul><li><code>npm run build</code> in <code>brandhub-web</code>.</li><li>Targeted Playwright coverage for collection selection, purpose-based creation, snapshot request payload, and Apply-to-Post prefill.</li><li><code>git diff --check</code> in each changed repository.</li></ul>',12)])])}const g=t(s,[["render",r]]);export{u as __pageData,g as default};
